import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

// One sidebar per navbar entry, each autogenerated from the directory it names, so a
// new skill or ADR appears without an edit here. README.md is the landing page.
const sidebars: SidebarsConfig = {
  readme: ['README'],
  // A generated index rather than the first skill: a link to one named skill would
  // break the day it is renamed.
  skills: [
    {
      type: 'category',
      label: 'Skills',
      link: { type: 'generated-index', slug: '/skills' },
      items: [{ type: 'autogenerated', dirName: 'skills' }],
    },
  ],
  adr: [{ type: 'autogenerated', dirName: 'doc/adr' }],
};

export default sidebars;
